<?php foreach($rows as $u):?><tr data-admin-row data-role="<?=h($u['role'])?>" data-status="<?=$u['status']?'active':'locked'?>" data-search="<?=h(implode(' ',[$u['id'],$u['full_name'],$u['email'],$u['phone']??'',$u['role']]))?>"><td><div class="admin-shop-cell"><span class="admin-person-avatar"><?=h(admin_initial($u['full_name']))?></span><span><strong><?=h($u['full_name'])?></strong><small>#<?=h($u['id'])?></small></span></div></td><td><?=h($u['email'])?><small class="admin-subtext"><?=h($u['phone']??'Chưa cập nhật SĐT')?></small></td><td><?=h(admin_role_name($u['role']))?></td><td><span class="admin-badge <?=$u['status']?'status-active':'status-locked'?>"><?=$u['status']?'Hoạt động':'Đã khóa'?></span></td><td><?=h(date('d/m/Y',strtotime($u['created_at'])))?></td><td><?php if($u['role']!=='admin'):?><form method="post" action="<?=h(url('admin_users'))?>" data-confirm="<?=$u['status']?'Khóa':'Mở khóa'?> tài khoản này?"><?php csrf_field();?><input type="hidden" name="action" value="admin_user_toggle"><input type="hidden" name="id" value="<?=h($u['id'])?>"><button class="admin-table-btn <?=$u['status']?'danger':'success'?>"><?=$u['status']?'Khóa':'Mở khóa'?></button></form><?php else:?><span class="admin-subtext">Được bảo vệ</span><?php endif;?></td></tr><?php endforeach;?></tbody></table><div class="admin-filter-empty" data-empty-for="admin-users-table" hidden>Không tìm thấy tài khoản phù hợp.</div><?php if(!$rows):?><div class="admin-empty-text">Chưa có tài khoản nào.</div><?php endif;?></div></section>
